from common import *
B='45魔画.txt'
make('zeng_bao','曾保',B,
'曾保是独眼的海盗与犯罪首领，也披着富商和海产公司经营者的外衣。他早年出身天地堂，与穆家长辈不睦，指使李彬偷取藏宝图，却被窃得图画后独自逃走的李彬背叛。多年过去，他在南洋建立以船只、枪手与商业垄断维持的势力，强迫渔民廉价出卖用生命换来的鱼翅，敢于反抗的人便遭毒打。他追查魔画并不依靠破解神秘学，而是利用别人：察觉木兰花难跟踪，转而盯住穆秀珍，再劫云四风逼问去向。云四风一度制住他，他却趁上车时猛踩油门脱身，又以准确射击切断电话线。他能识破空枪诱敌，不肯因为占优就贸然冲入房间，显出长期犯罪养成的谨慎。然而当南鲨岛据点被夺，他的愤怒和对财宝的贪求压倒谨慎，率直升机与枪手围攻，企图在军警抵达前毁掉抵抗者。他误以为财宝就藏在交战岛上，从空中投掷炸药，反被木兰花击爆落下的罐体，气浪使直升机坠毁。本人死亡、主要部下被捕，组织随之崩溃。他的强势来自枪法和已经建立的网络，不能在终局卡里无条件重新带回整支军力。',
'直升机坠毁爆炸死亡，主要部下被军警拘捕，犯罪组织崩溃。','精确射击与犯罪指挥','能以手枪击断电话线，利用监视、绑架、据点、航空载具和人力组织袭击。','组织与载具均是外部条件；躯体不能抵挡枪伤或坠机，藏宝判断也会错误。',[(428,440,'历史身份与犯罪组织。'),(620,640,'指使偷画而遭背叛。'),(1006,1018,'改追同伴、截住云四风。'),(1126,1186,'脱身、枪法与谨慎识骗。'),(2346,2494,'围攻、误认宝藏、坠亡和组织瓦解。')],
'独占财富和对岛民的支配，惩罚挑战其威信的人。',[('目标调查能力很强','直接跟踪易暴露','监视其关系人并利用人质追索。'),('敌人佯装弹尽','仍可能藏有后手','保持掩体，以火力和时间压迫。'),('据点被夺且权威遭嘲弄','相信财宝和报复机会同时出现','亲自调集外部兵力，可能为速胜冒险。')],aliases=('独眼曾保','曾瞎子'),roles=('反派',),scores=(4,0,2,3,5,4),tier='强',dead=True)
make('li_bin_magic_painting','李彬',B,
'李彬曾是天地堂中的年轻成员，在曾保指使下盗走关系组织大部分财富的图画。画到手后，他没有交给主使者，而是被独占宝藏的念头吸引，携画出走。失画造成组织互相猜忌，穆家长辈也受到错误指控；李彬承认自己没有料到众人会把责任算在他们头上，却不能因此免除背叛带来的后果。三十二年后，他仍未解出图中的秘密，已经沦落为衣衫破败、四处行乞的流浪汉。来见木兰花时，他以没有固定住处为由请求寄存图画，既保留对宝藏的执念，又希望得到保护。谈起曾保，他发抖、喝酒，害怕自己死在街头也无人问津。他能提供当年装船、巨量金银和南洋去向的记忆，却不能把这些记忆直接变成藏宝地点。木兰花根据他的伤势和时间关系，推测他已经被曾保控制、正在充当引路的棋子；原文也明说这尚是推测。故事没有给出他在结尾突然致富或洗清罪责的段落。其人物核心是长期贪念没有换来财富，反而把自己困在羞耻、恐惧和再次求生的选择中，适合在新的压力下表现迟疑、隐瞒与有限坦白。',
'被安排到警局获得保护；其是否继续向曾保传递信息未有明确逐项结论，未得到宝藏。','旧案记忆与隐瞒','能回忆偷画过程、装船场景和已知地域线索，以寄存与求助掩饰自己的利害。','没有破解图谜的能力；贫困、伤势和恐惧影响独立行动。',[(58,76,'寄存请求与落魄现状。'),(592,674,'偷画自述、执念和保护请求。'),(710,762,'受胁迫说为调查者推测。')],
'活下去并摆脱曾保，同时仍难完全放下自己耗去半生的宝藏。',[('过去的主使者重新出现','担忧旧账与灭口','寻求强者或警方保护。'),('有人要追问旧案','无法继续回避已知事实','边羞惭边作有限坦白。'),('藏宝谜有新进展','长期贪念再次被唤起','关注结果并可能隐瞒自己的期待。')],roles=('反派','单书主角'),uncertainties=['送画是否完全由曾保胁迫，是木兰花根据伤势作出的推测，不能把未展示的交易写成证实。'])
make('duman','都曼',B,
'都曼是南鲨岛村长的儿子，曾上大学，却未毕业便回到故乡。他熟悉岛屿、渔业和村民的生活，知道珍贵鱼翅为什么仍不能让辛苦捕鱼的人摆脱贫困：曾保的公司垄断收购，价格低得使人难以生活。他曾亲自去讲理，反遭打手痛殴，养伤三个月；村民拥护他，却宁可继续忍耐，也不愿他再受同样伤害。遇到木兰花等人，他既主动担任向导，又担心她们为当地人的事情蒙受损失。他愿意发动壮年人帮助反抗，同时接受先疏散居民、选择会用枪的人固守、请求军警支援的安排。战斗中他传递消息、联络伙伴，配合在窗口展示火力迫使敌人投降。他的勇气不是无视差距，父亲和他都清楚海盗拥有直升机和武装。犯罪组织覆灭后，他随众人去探查死亡岛，亲眼见到财宝实际已经变成废纸。虽然失望，他首先承认摆脱曾保控制本身已经改善生活；木兰花提出依法申请资源开采权、集资和提供合理工资的方向时，他又看见了新的希望。终局只建立了可能的道路，不能把他直接写成已经取得巨大矿业财富的企业家。',
'故乡摆脱曾保控制，参与发现水银湖床，准备考虑合法开发；尚未展示实际建矿或获利。','岛屿向导与社区动员','依靠当地知识、教育经历和村民信任组织联络、疏散与有限抵抗。','没有主角的特制武器或私人军队；工业开发仍需批准、资本与安全条件。',[(2062,2088,'教育、向导身份和被打后的处境。'),(2164,2168,'愿动员村民但接受节制。'),(2272,2302,'疏散和应对海盗实力。'),(2460,2502,'战场联络及胜利。'),(2604,2628,'废钞与开发前景。')],
'让乡亲摆脱暴力压价，靠自身劳动过更好的生活。',[('乡亲遭组织性欺压','个人交涉已经失败','寻求可靠帮助并说明真实处境。'),('反抗可能牵连平民','敌方武装远强于村民','先疏散再让有能力的人参与防守。'),('意外财富落空','社区仍有新的现实资源','承认失望，转向合法合作和劳动收益。')],scores=(2,0,1,2,2,2),tier='并')
make('huo_nansha','霍大哥',B,
'霍大哥是曾保海产公司在南鲨岛的负责人，四十岁左右，一脸横肉。这个据点以收购公司的名义经营，实际靠垄断和打手压迫村民；对外说是合法生意，与村民受到的毒打和低价收购形成强烈反差。木兰花等人来到码头时，先遇到的是他的收购人员和部下，他本人留在洋房楼上，没有立即冲在前面。穆秀珍打倒厅中多人，安妮又用麻醉针制住楼梯上的枪手，木兰花清点人数发现还缺一人，点名叫他出来。他此时才出现，仍以双方原本互不相干为由反驳干预，试图把犯罪压迫包装成自己的私人地盘。局面已完全受控，他不得不下楼，却又警告对方不可能永远留在这里，因为周围岛屿都属于曾保的势力范围。他能够联络曾保，认为援军最多数小时便会抵达，威胁中包含对长期暴力网络的依赖。木兰花正利用这个联络把首领引来，最终曾保死亡、主力被捕，他依靠的威慑也一并崩溃。其终局不能继续默认无人敢反抗的收购垄断；可演绎的逻辑是用合法外观、地盘和上级报复维系权力，在这些支柱失去后暴露出自身有限的行动空间。',
'据点被木兰花一行控制，上级战败、组织崩溃；没有个人脱身的明确描写。','据点管理与联络威胁','掌握当地公司、打手和与曾保的通讯联络，借上级势力维持服从。','部下和上级都是条件性资源；现场失去武装优势后无法凭威胁脱困。',[(2158,2164,'海产公司的掩护及负责人身份。'),(2208,2250,'隐藏、被迫现身、威胁和呼叫上级。'),(2482,2504,'军警接收俘虏、组织崩溃。')],
'维持据点控制和收益，依靠曾保的报复威慑对抗外来干预。',[('公司暴力遭到质问','尚有表面合法身份','声称只是合法生意，要求来者退出。'),('直属手下已经被制服','本人被点名要求现身','暂时服从但保留威胁语气。'),('认为上级可迅速增援','通讯渠道还在','联络援军并以未来报复压迫对手。')],roles=('反派',),scores=(2,0,1,2,2,2),tier='并')
